/**
 * Parser de arquivos Wavefront .obj para permitir carregar novos modelos .obj diretamente
 */
window.parseOBJModel = function(objText, name = 'CustomOBJ') {
    const verts = [];
    const normals = [];
    const faces = [];
    let currentRole = 'body';

    const lines = objText.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line || line.startsWith('#')) continue;
        const parts = line.split(/\s+/);
        const type = parts[0];
        if (type === 'v') {
            verts.push([parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])]);
        } else if (type === 'vn') {
            normals.push([parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])]);
        } else if (type === 'usemtl') {
            currentRole = parts[1] || 'body';
        } else if (type === 'f') {
            const vIdx = [];
            let nIdx = -1;
            for (let j = 1; j < parts.length; j++) {
                const sub = parts[j].split('/');
                vIdx.push(parseInt(sub[0], 10) - 1);
                if (sub.length >= 3 && sub[2]) {
                    nIdx = parseInt(sub[2], 10) - 1;
                }
            }
            if (vIdx.length >= 3) {
                let cx = 0, cy = 0, cz = 0;
                for (const idx of vIdx) {
                    const v = verts[idx] || [0, 0, 0];
                    cx += v[0]; cy += v[1]; cz += v[2];
                }
                cx /= vIdx.length; cy /= vIdx.length; cz /= vIdx.length;

                let n = [0, 1, 0];
                if (nIdx >= 0 && normals[nIdx]) {
                    n = normals[nIdx];
                } else {
                    const v0 = verts[vIdx[0]] || [0,0,0];
                    const v1 = verts[vIdx[1]] || [0,0,0];
                    const v2 = verts[vIdx[2]] || [0,0,0];
                    const ax = v1[0] - v0[0], ay = v1[1] - v0[1], az = v1[2] - v0[2];
                    const bx = v2[0] - v0[0], by = v2[1] - v0[1], bz = v2[2] - v0[2];
                    const nx = ay * bz - az * by;
                    const ny = az * bx - ax * bz;
                    const nz = ax * by - ay * bx;
                    const len = Math.hypot(nx, ny, nz) || 1;
                    n = [nx / len, ny / len, nz / len];
                }
                faces.push({ v: vIdx, n, c: [cx, cy, cz], r: currentRole });
            }
        }
    }
    return { name, verts, faces };
};

